{
  "name": "@jcodesmore/slack-for-ai-agents",
  "version": "0.1.1",
  "description": "Slack workspace admin tools for AI coding agents — natural-language management of channels, usergroups, Block Kit messages, scheduled posts, canvases, and full workspace templates",
  "type": "module",
  "main": "dist/server.js",
  "bin": {
    "slack-mcp": "./dist/server.js"
  },
  "files": [
    "dist",
    "skills",
    "agents",
    "scripts",
    "templates",
    ".claude-plugin",
    "CHANGELOG.md",
    "LICENSE",
    "README.md"
  ],
  "license": "Apache-2.0",
  "author": {
    "name": "JCodesMore",
    "url": "https://github.com/JCodesMore"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JCodesMore/slack-for-ai-agents.git"
  },
  "homepage": "https://github.com/JCodesMore/slack-for-ai-agents",
  "bugs": {
    "url": "https://github.com/JCodesMore/slack-for-ai-agents/issues"
  },
  "keywords": [
    "mcp",
    "model-context-protocol",
    "slack",
    "slack-bot",
    "ai-agents",
    "claude-code",
    "block-kit",
    "workspace-admin",
    "plugin"
  ],
  "engines": {
    "node": ">=18.0.0"
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "start": "node dist/server.js",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.28.0",
    "@slack/web-api": "^7.10.0",
    "zod": "^3.23.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^5.5.0"
  }
}

{
  "name": "AI Research Lab",
  "description": "ML / AI research group workspace: paper club, experiments, evals, infra, code-review, plus a private leads channel and Researchers / Lab Leads usergroups.",
  "channels": [
    {
      "name": "paper-club",
      "topic": "Weekly paper readings.",
      "purpose": "Share papers, schedule readings, post discussion threads."
    },
    {
      "name": "experiments",
      "topic": "Active experiments and live results.",
      "purpose": "Run logs, hypothesis posts, result threads. Tag with model + dataset."
    },
    {
      "name": "model-eval",
      "topic": "Model evals, benchmarks, regression alerts.",
      "purpose": "Evaluation runs, leaderboard updates, regression triage."
    },
    {
      "name": "infra",
      "topic": "Compute, datasets, pipelines.",
      "purpose": "Cluster issues, dataset versioning, pipeline ownership."
    },
    {
      "name": "code-review",
      "topic": "Code reviews, PRs, design docs.",
      "purpose": "Cross-team review of model code, data tooling, eval harnesses."
    },
    {
      "name": "general",
      "topic": "Casual lab chat.",
      "purpose": "Off-topic, intros, shoutouts."
    },
    {
      "name": "lab-leads",
      "is_private": true,
      "topic": "Lab leadership.",
      "purpose": "Direction, hiring, headcount, budget."
    }
  ],
  "usergroups": [
    {
      "name": "Researchers",
      "handle": "researchers",
      "description": "Active researchers in the lab.",
      "channel_ids": ["paper-club", "experiments", "model-eval", "general"]
    },
    {
      "name": "Lab Leads",
      "handle": "lab-leads",
      "description": "Lab leadership.",
      "channel_ids": ["lab-leads"]
    }
  ]
}

#!/usr/bin/env node

import { existsSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath, pathToFileURL } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const pluginRoot = join(__dirname, '..');
const entrypoint = join(pluginRoot, 'dist', 'server.js');

if (!existsSync(entrypoint)) {
  process.stderr.write(
    '[slack-for-ai-agents] dist/server.js not found. Run `npm install && npm run build` in the plugin directory, or restart your AI coding agent so the SessionStart hook can build it.\n'
  );
  process.exit(1);
}

await import(pathToFileURL(entrypoint).href);

