  server.registerTool(
    'slack_create_channel_canvas',
    {
      description:
        "Creates a canvas attached to a channel's Canvas tab via conversations.canvases.create. " +
        'If the channel already has a canvas, returns its existing canvas_id (no overwrite). ' +
